import {saveFile} from './file-save.mjs';
import {escapeHtml as esc} from './core.mjs';
import {PERIODS,normalizeMomentsSettings,validateMomentsSettings,getMoment,getPeriodAt} from './moments-core.mjs';

const timezone=()=>{try{return Intl.DateTimeFormat().resolvedOptions().timeZone||'Fuso local do aparelho';}catch{return 'Fuso local do aparelho';}};
export function createMomentsUI(ctx){
 const copy=(demo,live)=>globalThis.mentraProduction?live:demo;
 const {getState,setState,save,toast,render,heading,button,link,icon,getRoute}=ctx;
 let paused=false,showAll=false,speaking=false,utterance=null,voiceSequence=0,sharing=false,routeEpoch=0;const preparedCards=new Map(),preparingCards=new Map();
 const settings=()=>normalizeMomentsSettings(getState().moments);
 const selectedPeriod=()=>PERIODS.some(p=>p.id===getRoute().split('/')[1])?getRoute().split('/')[1]:getPeriodAt(new Date());
 const currentMoment=()=>getMoment(selectedPeriod(),settings().christian);
 const status=text=>{const el=document.querySelector('#moment-status');if(el)el.textContent=text;else toast(text);};
 const supportsSpeech=()=>typeof window!=='undefined'&&!!window.speechSynthesis&&typeof globalThis.SpeechSynthesisUtterance==='function';
 function updateSpeechControls(){const el=document.querySelector('[data-action="moment-listen"]');if(el){el.textContent=speaking?'Parar leitura':'Ouvir mensagem';el.setAttribute?.('aria-pressed',String(speaking));}}
 function stopSpeech(message=''){voiceSequence++;if(utterance){utterance.onend=null;utterance.onerror=null;utterance.onstart=null;}if(speaking&&supportsSpeech())window.speechSynthesis.cancel();utterance=null;speaking=false;updateSpeechControls();if(message)status(message);}
 function listen(){if(speaking){stopSpeech('Leitura interrompida.');return;}if(!supportsSpeech()){status('A leitura em voz alta não está disponível neste navegador. Você pode ler a frase e baixar o card.');return;}const moment=currentMoment(),token=++voiceSequence;
  try{window.speechSynthesis.cancel();utterance=new SpeechSynthesisUtterance(`${moment.text}${moment.reference?` Paráfrase inspirada em ${moment.reference}.`:''}`);utterance.lang='pt-BR';utterance.rate=.92;utterance.pitch=1;const voices=window.speechSynthesis.getVoices?.()||[];const voice=voices.find(v=>/^pt[-_]BR$/i.test(v.lang))||voices.find(v=>/^pt/i.test(v.lang));if(voice)utterance.voice=voice;
   utterance.onstart=()=>{if(token===voiceSequence)status('Lendo com a voz disponível no aparelho.');};utterance.onend=()=>{if(token!==voiceSequence)return;speaking=false;utterance=null;updateSpeechControls();status('Leitura concluída.');};utterance.onerror=()=>{if(token!==voiceSequence)return;speaking=false;utterance=null;updateSpeechControls();status('Não foi possível reproduzir a voz. Tente novamente ou leia a frase na tela.');};speaking=true;updateSpeechControls();status('Preparando a voz disponível no aparelho…');window.speechSynthesis.speak(utterance);
  }catch{stopSpeech();status('Não foi possível iniciar a voz neste navegador. A mensagem continua disponível em texto.');}}
 function renderTodayCard(){const s=settings(),moment=getMoment(getPeriodAt(new Date()),s.christian);return `<section class="moment-today-card" aria-labelledby="home-moment-title"><span class="round-icon" aria-hidden="true">${icon('spark')}</span><div class="moment-today-copy"><span class="eyebrow">MOMENTOS MENTRA</span><h2 id="home-moment-title">Uma mensagem para dar um novo ânimo ao seu dia</h2><p>Motivação e reflexões para começar a manhã, renovar o foco à tarde e encerrar a noite. Escolha seu momento e compartilhe a mensagem que fizer sentido para você.</p>${s.enabled?'':'<p class="moment-today-paused">Seus momentos estão pausados. Você pode abrir uma mensagem quando quiser.</p>'}</div>${link('<span>Ver minha mensagem motivacional do dia</span>'+icon('arrow'),'momentos/'+moment.period,'primary moment-today-cta')}</section>`;}
 function notificationPreviews(){const s=settings();return `<section class="card moment-preview-panel"><div class="section-head"><div><h2>Como o lembrete poderia aparecer</h2><p class="small muted">Prévia dentro do app. Toque para abrir a mensagem.</p></div></div><div class="moment-notification-grid">${PERIODS.map(p=>{const m=getMoment(p.id,s.christian),active=s.enabled&&s.periods[p.id].enabled;return `<a class="moment-notification ${active?'':'is-muted'}" href="#/momentos/${p.id}"><div><i class="brand-mark brand-mark-mini" aria-hidden="true"><img src="assets/mentra-logo-original.png" alt="" width="1254" height="1254"></i><span>MENTRA LIFE</span><time>${esc(s.periods[p.id].time)}</time></div><strong>${esc(m.title)}</strong><p>${p.id==='morning'?'Seu dia pode começar com um pequeno passo.':p.id==='afternoon'?'Uma pausa pode abrir espaço para o próximo passo.':'Um convite para desacelerar e encerrar o dia.'}</p><small>${active?'Simulação · toque para abrir':'Pausado na preferência · toque para explorar'}</small></a>`;}).join('')}</div><p class="moment-simulation-note">${copy('Nenhuma notificação será enviada. Horários e opções ficam salvos apenas nesta demonstração.','Esta é uma prévia ilustrativa. O banner push real é discreto e não contém o texto da mensagem. Configure o dispositivo e os avisos na Caixa de entrada.')}</p></section>`;}
 function renderSettings(){const s=settings();return `<section class="card moment-settings"><div><span class="eyebrow">VOCÊ ESCOLHE O RITMO</span><h2>Seus três momentos</h2><p>${copy('Horários de exemplo no fuso do aparelho:','Horários para suas preferências. O envio usa o fuso escolhido nos avisos push; fuso deste aparelho:')} <b>${esc(timezone())}</b>.</p></div><form id="moment-settings-form"><label class="moment-check main-check"><input name="enabled" type="checkbox" ${s.enabled?'checked':''}><span><b>Ativar os Momentos Mentra</b><small>${copy('Preferência de demonstração. Desative para pausar todos.','Desative para pausar os Momentos e seus envios pendentes.')}</small></span></label><div class="moment-schedule">${PERIODS.map(p=>`<div><label class="moment-check"><input name="${p.id}Enabled" type="checkbox" ${s.periods[p.id].enabled?'checked':''}><span>${esc(p.label)}</span></label><label for="moment-time-${p.id}" class="sr-only">Horário da ${p.label.toLowerCase()}</label><input id="moment-time-${p.id}" name="${p.id}Time" type="time" value="${esc(s.periods[p.id].time)}" required aria-label="Horário: ${esc(p.label)}"></div>`).join('')}</div><label class="moment-check faith-check"><input name="christian" type="checkbox" ${s.christian?'checked':''}><span><b>Quero mensagens com inspiração cristã</b><small>Escolha opcional, desativada por padrão. Textos autorais e paráfrases identificadas, sem presumir sua religião.</small></span></label><p id="moment-settings-error" class="form-error" role="alert"></p><button class="primary" type="submit">Salvar minhas preferências</button><p class="small muted">Você pode mudar ou pausar a qualquer momento. ${copy('Esta tela não pede permissão para notificações nem agenda envios.','A permissão é solicitada somente ao ativar o dispositivo na Caixa de entrada. Se você também ativou os avisos de Momentos, os horários salvos atualizam a fila.')}</p></form></section>`;}
 function renderPage(){const s=settings(),period=selectedPeriod(),m=currentMoment(),words=m.text.split(/\s+/);return heading('MOMENTOS MENTRA','Uma palavra de calma. Um novo fôlego.','Manhã, tarde e noite. Escolha uma mensagem para este momento.')+`<div class="notice warm moment-demo-warning">${icon('info')} ${copy('Demonstração: os lembretes são simulados dentro do app. Não há push, envio ou agendamento real.','Para receber lembretes com o app fechado, ative o dispositivo e os avisos de Momentos na Caixa de entrada. A entrega depende do navegador e do aparelho.')}</div><nav class="moment-tabs" aria-label="Momento do dia">${PERIODS.map(p=>link(`${p.label}<small>${esc(s.periods[p.id].time)}</small>`,'momentos/'+p.id,'moment-tab '+(p.id===period?'selected':''))).join('')}</nav><div class="moment-layout"><section class="moment-stage ${paused?'moment-paused':''} ${showAll?'moment-show-all':''}"><div class="moment-stage-top"><span>${s.christian?'INSPIRAÇÃO CRISTÃ · POR SUA ESCOLHA':'UMA MENSAGEM PARA VOCÊ'}</span><span>${esc(m.label)}</span></div><div class="moment-face" aria-hidden="true"><i></i><img src="assets/mentra-face.png" alt="" width="1280" height="1280" draggable="false"></div><div class="moment-words"><h2>${esc(m.title)}</h2><p class="sr-only">${esc(m.text)}</p><p class="moment-message" aria-hidden="true">${words.map((w,i)=>`<span class="moment-word" style="--word-delay:${(i*.12).toFixed(2)}s">${esc(w)} </span>`).join('')}</p><p class="moment-attribution">${esc(m.attribution)}${m.reference?` · ${esc(m.reference)}`:''}</p></div><div class="moment-stage-bottom"><span>mentra <small>LIFE</small></span>${button(paused?'Retomar movimento':'Pausar movimento','moment-pause','moment-motion-button',`aria-pressed="${paused}"`)}</div></section><aside class="moment-actions card"><span class="eyebrow">LEVE ESTA MENSAGEM COM VOCÊ</span><h2>Do seu momento<br>para o seu dia.</h2><p>Ouça, guarde ou compartilhe a frase com quem você quiser.</p><div class="entry-document-actions">${button(`${icon('spark')} Ouvir mensagem`,'moment-listen','primary','aria-pressed="false"')}${button('Mostrar frase inteira','moment-show-all','outline')}${button(`${icon('down')} Baixar card para Story`,'moment-download','outline')}${button('Compartilhar card…','moment-share','outline')}</div><p id="moment-status" class="small moment-status" role="status" aria-live="polite"></p><p class="small muted">A voz é a disponível no aparelho e só começa ao tocar em Ouvir. A cabeça tem movimento decorativo, sem sincronização da boca.</p><a class="moment-card-preview" ${globalThis.mentraNative?'data-action="moment-download"':''} href="${esc(m.cardPath)}" download="mentra-${esc(m.id)}.png"><img src="${esc(m.cardPath)}" alt="Prévia do card vertical com a mesma frase. PNG estático." loading="lazy"><span>PNG vertical · 1080 × 1920<br>Sem seus dados pessoais</span></a><p class="small muted">O compartilhamento abre as opções do dispositivo, quando compatível. Você escolhe o destino e confirma. Sem publicação automática.</p></aside></div><div class="moment-support-grid">${renderSettings()}${notificationPreviews()}</div>`;}
 async function cardBlob(moment){const response=await fetch(moment.cardPath);if(!response.ok)throw new Error('fetch');const blob=await response.blob();const bytes=new Uint8Array(await blob.slice(0,8).arrayBuffer());if(bytes.join(',')!=='137,80,78,71,13,10,26,10')throw new Error('png');return new Blob([blob],{type:'image/png'});}
 function downloadCard(moment){if(globalThis.mentraNative){void cardBlob(moment).then(blob=>saveFile(`mentra-${moment.id}.png`,blob)).catch(()=>status('Não foi possível compartilhar a imagem. Tente novamente.'));return;}const a=document.createElement('a');a.href=moment.cardPath;a.download=`mentra-${moment.id}.png`;document.body.appendChild(a);a.click();a.remove();status('Download do PNG solicitado. Verifique os arquivos do seu dispositivo.');}
 function prepareCard(moment){if(preparedCards.has(moment.id))return Promise.resolve(preparedCards.get(moment.id));if(preparingCards.has(moment.id))return preparingCards.get(moment.id);const promise=cardBlob(moment).then(blob=>{if(typeof File!=='function')return null;const file=new File([blob],`mentra-${moment.id}.png`,{type:'image/png'});preparedCards.set(moment.id,file);return file;}).catch(()=>null).finally(()=>preparingCards.delete(moment.id));preparingCards.set(moment.id,promise);return promise;}
 function syncAfterRender(){if(!getRoute().startsWith('momentos'))return;updateSpeechControls();if(typeof File==='function'&&globalThis.navigator?.share)void prepareCard(currentMoment());}
 async function shareCard(){if(sharing)return;const moment=currentMoment(),epoch=routeEpoch;if(typeof File!=='function'||!navigator.share||!navigator.canShare){status('Compartilhamento de arquivos indisponível. Use Baixar card para Story e envie pelo aplicativo que preferir.');return;}const file=preparedCards.get(moment.id);if(!file){status('Preparando o card. Toque em Compartilhar novamente quando estiver pronto.');const ready=await prepareCard(moment);if(epoch!==routeEpoch)return;status(ready?'Card pronto. Toque em Compartilhar para escolher o destino.':'Não foi possível preparar o compartilhamento. Use Baixar card para Story.');return;}sharing=true;try{if(!navigator.canShare({files:[file]})){status('Este navegador não compartilha PNG. Use Baixar card para Story.');return;}await navigator.share({files:[file],title:'Momentos Mentra'});if(epoch!==routeEpoch)return;status('Card entregue ao compartilhamento do dispositivo. A Mentra não confirma a publicação ou o envio.');}catch(error){if(epoch!==routeEpoch)return;status(error.name==='AbortError'?'Compartilhamento cancelado ou sem destino disponível. Você ainda pode baixar o card.':'Não foi possível compartilhar. Use Baixar card para Story.');}finally{sharing=false;}}
 function handleClick(action){if(!action.startsWith('moment-'))return false;if(action==='moment-listen')listen();else if(action==='moment-pause'){paused=!paused;const stage=document.querySelector('.moment-stage');stage?.classList[paused?'add':'remove']('moment-paused');const control=document.querySelector('[data-action="moment-pause"]');if(control){control.textContent=paused?'Retomar movimento':'Pausar movimento';control.setAttribute?.('aria-pressed',String(paused));}if(paused)stopSpeech('Movimento e leitura pausados.');}else if(action==='moment-show-all'){showAll=true;document.querySelector('.moment-stage')?.classList.add('moment-show-all');}else if(action==='moment-download')downloadCard(currentMoment());else if(action==='moment-share')void shareCard();return true;}
 function handleSubmit(form){if(form.id!=='moment-settings-form')return false;if(!form.checkValidity()){form.reportValidity();return true;}const f=Object.fromEntries(new FormData(form));const draft={enabled:!!f.enabled,christian:!!f.christian,periods:Object.fromEntries(PERIODS.map(p=>[p.id,{enabled:!!f[p.id+'Enabled'],time:f[p.id+'Time']}]))};const result=validateMomentsSettings(draft);if(!result.ok){document.querySelector('#moment-settings-error').textContent=result.errors.join(' ');return true;}const before=getState();setState({...before,moments:result.settings});if(save()===false){setState(before);document.querySelector('#moment-settings-error').textContent='Não foi possível salvar. As preferências anteriores foram mantidas.';return true;}stopSpeech();render();toast('Preferências salvas neste navegador. Nenhuma notificação foi agendada.');return true;}
 function routeChanged(){routeEpoch++;stopSpeech();showAll=paused;}
 if(typeof document.addEventListener==='function')document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSpeech();});
 if(typeof window.addEventListener==='function')window.addEventListener('pagehide',()=>stopSpeech());
 return {renderPage,renderTodayCard,handleClick,handleSubmit,routeChanged,stopSpeech,syncAfterRender};
}
